import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './WhitespaceConverter.css';

const WhitespaceConverter = () => {
  const [leftText, setLeftText] = useState('');
  const [rightText, setRightText] = useState('');

  const showWhitespaceLeftToRight = () => {
    const converted = leftText
      .replace(/ /g, '·')
      .replace(/\t/g, '→   ')
      .replace(/\n/g, '↵\n');
    setRightText(converted);
  };

  const hideWhitespaceLeftToRight = () => {
    const converted = leftText
      .replace(/·/g, ' ')
      .replace(/→   /g, '\t')
      .replace(/↵\n/g, '\n')
      .replace(/↵/g, '');
    setRightText(converted);
  };

  const showWhitespaceRightToLeft = () => {
    const converted = rightText
      .replace(/ /g, '·')
      .replace(/\t/g, '→   ')
      .replace(/\n/g, '↵\n');
    setLeftText(converted);
  };

  const hideWhitespaceRightToLeft = () => {
    const converted = rightText
      .replace(/·/g, ' ')
      .replace(/→   /g, '\t')
      .replace(/↵\n/g, '\n')
      .replace(/↵/g, '');
    setLeftText(converted);
  };

  const clearAll = () => {
    setLeftText('');
    setRightText('');
  };

  const swapSides = () => {
    const temp = leftText;
    setLeftText(rightText);
    setRightText(temp);
  };

  return (
    <div className="whitespace-converter-page">
      <div className="whitespace-header">
        <Link to="/" className="back-button">← Back to Home</Link>
        <h1>Whitespace Converter</h1>
        <p>Convert whitespace to visible characters and back</p>
      </div>

      <div className="whitespace-container">
        <div className="controls-section">
          <div className="legend">
            <span className="legend-item">
              <span className="symbol">·</span> = Space
            </span>
            <span className="legend-item">
              <span className="symbol">→</span> = Tab
            </span>
            <span className="legend-item">
              <span className="symbol">↵</span> = Newline
            </span>
          </div>
          <button onClick={swapSides} className="swap-button">
            ⇄ Swap Sides
          </button>
        </div>

        <div className="text-container">
          <div className="text-box">
            <h3>Left Panel</h3>
            <textarea
              value={leftText}
              onChange={(e) => setLeftText(e.target.value)}
              placeholder="Paste your text here..."
              className="whitespace-textarea"
            />
          </div>
          <div className="text-box">
            <h3>Right Panel</h3>
            <textarea
              value={rightText}
              onChange={(e) => setRightText(e.target.value)}
              placeholder="Result will appear here..."
              className="whitespace-textarea"
            />
          </div>
        </div>

        <div className="button-section">
          <div className="button-group">
            <h4>Left → Right</h4>
            <div className="button-row">
              <button onClick={showWhitespaceLeftToRight} className="show-button">
                Show →
              </button>
              <button onClick={hideWhitespaceLeftToRight} className="hide-button">
                Hide →
              </button>
            </div>
          </div>

          <div className="button-group">
            <h4>Right → Left</h4>
            <div className="button-row">
              <button onClick={showWhitespaceRightToLeft} className="show-button">
                ← Show
              </button>
              <button onClick={hideWhitespaceRightToLeft} className="hide-button">
                ← Hide
              </button>
            </div>
          </div>

          <button onClick={clearAll} className="clear-button">
            Clear All
          </button>
        </div>
      </div>
    </div>
  );
};

export default WhitespaceConverter;
